//! Recorded metal impacts and heavier crash debris, triggered by collision speed.

use crate::sound::SAMPLE_RATE;

// Canonical mono 48 kHz signed 16-bit WAVs, generated by the adjacent asset script.
const METAL: &[u8] = include_bytes!("../../data/audio/impacts/metal.wav");
const CRASH: &[u8] = include_bytes!("../../data/audio/impacts/crash.wav");
const WAV_HEADER: usize = 44;

#[derive(Default)]
struct Voice {
    position: f32,
    rate: f32,
    decay: f32,
    envelope: f32,
    strength: f32,
    heavy: f32,
}

#[derive(Default)]
pub struct Impacts {
    voices: [Voice; 8],
    cooldown: f32,
}

pub fn hit(impacts: &mut Impacts, speed: f32) {
    if speed <= 1.5 || impacts.cooldown > 0.0 {
        return;
    }
    // Preserve existing tails. If all voices are busy, discard extra contacts.
    let Some(voice) = impacts
        .voices
        .iter_mut()
        .find(|voice| voice.strength == 0.0)
    else {
        return;
    };
    let strength = ((speed - 1.5) / 9.0).clamp(0.0, 1.0);
    let heavy = ((strength - 0.2) / 0.6).clamp(0.0, 1.0);
    // The original blend saturates at 10.5 m/s. Keep gentle impacts intact,
    // then sharpen the attack and shorten the debris for faster collisions.
    // Speed is the component into the obstacle, not total road speed.
    let severity = ((speed - 10.5) / 25.0).clamp(0.0, 1.0);
    *voice = Voice {
        position: 0.0,
        rate: 1.0 + severity * 0.8,
        decay: (-severity / (SAMPLE_RATE * 0.12)).exp(),
        envelope: 1.0,
        strength: strength * (1.0 + severity * 0.6),
        heavy: heavy * heavy * (3.0 - 2.0 * heavy),
    };
    impacts.cooldown = 0.09;
}

pub fn suppress(impacts: &mut Impacts) {
    *impacts = Impacts::default();
}

pub fn sample(impacts: &mut Impacts) -> f32 {
    impacts.cooldown = (impacts.cooldown - 1.0 / SAMPLE_RATE).max(0.0);
    let mut output = 0.0;
    for voice in &mut impacts.voices {
        if voice.strength == 0.0 {
            continue;
        }
        let metal = interpolated(METAL, voice.position);
        let crash = interpolated(CRASH, voice.position);
        output += (metal * (1.0 - voice.heavy) * 0.18 + crash * voice.heavy * 0.26)
            * voice.strength
            * voice.envelope;
        voice.position += voice.rate;
        voice.envelope *= voice.decay;
        let clip = if voice.heavy > 0.0 { CRASH } else { METAL };
        if voice.position >= ((clip.len() - WAV_HEADER) / 2) as f32 || voice.envelope < 0.0001 {
            voice.strength = 0.0;
        }
    }
    output
}

fn interpolated(clip: &[u8], position: f32) -> f32 {
    let frame = position as usize;
    let current = point(clip, frame);
    current + (point(clip, frame + 1) - current) * position.fract()
}

fn point(clip: &[u8], frame: usize) -> f32 {
    let offset = WAV_HEADER + frame * 2;
    match clip.get(offset..offset + 2) {
        Some(bytes) => i16::from_le_bytes([bytes[0], bytes[1]]) as f32 / 32768.0,
        None => 0.0,
    }
}

